[{"role": "system", "content": "You state the laws of a simulated world of people: which counts it keeps that must never change except in the ways its laws allow. The world's structure is fixed; you add no fields, moves or processes. Some moves and processes are compiled rules that are already exact (marked compiled, and listed per field under written_by_compiled); a total law on a field they write must list every one of them. Counts that are only clocks or tallies of what happened (rounds left, times something was raised) are not resources. Return one JSON object {"resources": [...], "laws": [...]} and nothing else.
resources: Optional top-level list of the things this world keeps count of that must never appear or vanish except in the ways its laws allow: [{resource_id (lowercase-slug), says (one plain sentence), kept_in: [{component, field}] naming every integer or number field that holds an amount of it}]. Money, stock of goods and stored materials are typical; feelings and scores are not.
laws: Optional top-level list of what must stay true about those resources, in this world's own terms. Two shapes. A total law: {law_id (lowercase-slug), says, resource, may_change_by: [action kinds, or 'process:<name>' for something the world does by itself]} means the resource's world total changes only through those; every other move only moves it between holders. List every move that makes the resource AND every move that uses it up: logs are made by cutting and used up by sawing them into slats, so a logs law lists both cut-cedar and saw-slats; a pencils law lists the move that makes pencils and the move that packs them into boxes or a customer uses them. If the world itself adds or removes some each round (trees regrow, bread goes stale), list it as 'process:<a short slug>'; the rules writer will give that process exactly this id. A move you leave out will be refused whenever it changes the total. A pairing law: {law_id, says, move: action kind, gives: {resource, from, to}, pays: {resource, from, to}} means that move always hands one thing over in return for another, where from and to are 'actor' or one of that action's entity_ref field names and whoever gives is whoever is paid (a sale: gives pencils shop->customer, pays money customer->shop). In a pairing law the one who pays is `actor`; a sale the seller starts is written as the buyer's `buy-...` move. Use [] for both when nothing in the description is kept count of."}, {"role": "user", "content": "{
 "description": "A partnership of four countries and a regional health network must decide by a deadline whether to activate a cross-border bio-surveillance early-warning system. Technical, legal, logistics and community groups each raise small, true but local concerns through their own channels to different members. Members meet regularly; the concerns slow meetings, reopen settled issues and make support conditional, which can delay or block deployment.",
 "numeric_fields": [
  {
   "component": "validation_decision",
   "field": "assents",
   "held_by": [
    "validation-decision"
   ],
   "written_by_compiled": [
    "record-assent",
    "withdraw-assent"
   ]
  },
  {
   "component": "actor_position",
   "field": "assent_weight",
   "held_by": [
    "actor-position"
   ],
   "written_by_compiled": []
  },
  {
   "component": "moment",
   "field": "ticks_until",
   "held_by": [
    "moment"
   ],
   "written_by_compiled": [
    "process:moment-countdown",
    "process:moment-occurs"
   ]
  },
  {
   "component": "moment",
   "field": "every_ticks",
   "held_by": [
    "moment"
   ],
   "written_by_compiled": []
  },
  {
   "component": "moment",
   "field": "occurrences",
   "held_by": [
    "moment"
   ],
   "written_by_compiled": [
    "process:moment-occurs"
   ]
  }
 ],
 "moves": [
  {
   "kind": "communicate",
   "description": "Deliver one represented information item to its declared recipient.",
   "compiled": true
  },
  {
   "kind": "send-report",
   "description": "Send your own words directly to another person; records exposure, not belief or agreement.",
   "compiled": true
  },
  {
   "kind": "record-assent",
   "description": "record assent",
   "compiled": true
  },
  {
   "kind": "withdraw-assent",
   "description": "withdraw assent",
   "compiled": true
  },
  {
   "kind": "state-supportive",
   "description": "state supportive",
   "compiled": true
  },
  {
   "kind": "state-concerned",
   "description": "state concerned",
   "compiled": true
  },
  {
   "kind": "state-undecided",
   "description": "state undecided",
   "compiled": true
  },
  {
   "kind": "request-review",
   "description": "request review",
   "compiled": true
  },
  {
   "kind": "complete-validation",
   "description": "complete validation",
   "compiled": true
  },
  {
   "kind": "repair-condition",
   "description": "repair condition",
   "compiled": true
  },
  {
   "kind": "activate",
   "description": "activate",
   "compiled": true
  },
  {
   "kind": "schedule-regular-meetings",
   "description": "Create or update the partnership's recurring meeting schedule for considering activation.",
   "compiled": false
  },
  {
   "kind": "defer-agenda-item",
   "description": "Record that an activation agenda item is deferred to a later meeting, delaying its consideration.",
   "compiled": false
  },
  {
   "kind": "reopen-deliberative-issue",
   "description": "Reopen a previously settled issue in the activation deliberation for further consideration.",
   "compiled": false
  }
 ]
}"}]

