":{"participant":{"name":"decision","path":"components.validation_decision.review"}},"op":"eq","right":{"literal":"settled"}},{"label":"This reopening has not already been recorded by the Partnership","left":{"participant":{"name":"actor","path":"components.work.reopen_deliberative_issue_done"}},"op":"eq","right":{"literal":false}},{"label":"The Partnership and activation decision must be in the same place","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"decision","path":"location.location_id"}}}],"effects":[{"participant":"decision","path":"components.validation_decision.review","op":"set","value":{"literal":"reopened"}},{"participant":"actor","path":"components.work.reopen_deliberative_issue_done","op":"set","value":{"literal":true}}],"limits":["No represented field stores the issue text or distinguishes multiple settled issues; only the decision's review state records reopening.","This does not change technical validation, hold, public positions, or assent. A settled review state is required and is not produced by these mechanics."],"tests":["A named issue can be reopened when the decision review is recorded as settled and the Partnership has not already recorded a reopening.","An unexpressed or unsettled review, empty issue, already-recorded reopening, non-Partnership actor, or decision in another place is refused."],"semantic_bindings":["The decision's review field changes from settled to reopened.","The represented world cannot record which issue was reopened."]}],"processes":[{"process_id":"meeting-countdown","rationale":"The represented work cycle's countdown advances each round while positive.","selector":{"categories":["work-cycle"],"components":["moment"]},"checks":[{"label":"The next meeting is more than zero rounds away","left":{"participant":{"name":"it","path":"components.moment.ticks_until"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"it","path":"components.moment.ticks_until","op":"subtract","value":{"literal":1}}],"timing":"each_round"},{"process_id":"meeting-cycle-recurrence","rationale":"When the work-cycle countdown reaches zero, record a cycle occurrence and restart the countdown using its recurring interval.","selector":{"categories":["work-cycle"],"components":["moment"]},"checks":[{"label":"The meeting cycle countdown has reached zero","left":{"participant":{"name":"it","path":"components.moment.ticks_until"}},"op":"eq","right":{"literal":0}},{"label":"The meeting cycle has a positive recurring interval","left":{"participant":{"name":"it","path":"components.moment.every_ticks"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"it","path":"components.moment.occurrences","op":"add","value":{"literal":1}},{"participant":"it","path":"components.moment.ticks_until","op":"set","value":{"participant":{"name":"it","path":"components.moment.every_ticks"}}}],"timing":"each_round"}],"terminal":null}"}, {"role": "user", "content": "The local causal compiler rejected that proposal. Compiler error: ActionDeclarationError: actor_selector names unknown components: ['location']. Return a corrected JSON object only. State paths in participant/path and effect/path fields must be copied EXACTLY from allowed_state_paths; do not abbreviate component containers (for example use portable.portable, not portable)."}]

